DROP TABLE IF EXISTS `bms_city`;
CREATE TABLE `bms_city` (
  `id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID',
  `code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市编码',
  `pcode` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上级编码',
  `pcity` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上级城市名称',
  `level` int(3) DEFAULT NULL COMMENT '层级',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市名称',
  `py` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拼音',
  `index_letter` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市拼音首字母',
  `if_hot` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否热门',
  `latitude` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纬度',
  `longitude` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经度',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(32) CHARACTER SET utf8 DEFAULT NULL COMMENT '创建人',
  `create_time` date DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8 DEFAULT NULL COMMENT '修改人',
  `update_time` date DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) CHARACTER SET utf8 DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(10) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(3) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  `status` varchar(3) CHARACTER SET utf8 DEFAULT '1' COMMENT '是否启用',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='城市信息';

