-- ----------------------------
-- Table structure for rms_company
-- ----------------------------
DROP TABLE IF EXISTS `rms_company`;
CREATE TABLE `rms_company` (
  `id` varchar(50) NOT NULL,
  `logo` varchar(255) DEFAULT NULL COMMENT '公司logo',
  `name` varchar(15) DEFAULT NULL COMMENT '公司简称',
  `full_name` varchar(30) DEFAULT NULL COMMENT '公司全称',
  `industry_id` int(19) DEFAULT NULL COMMENT '所属行业',
  `industry_name` varchar(50) DEFAULT NULL COMMENT '所在行业',
  `staff_size` varchar(20) DEFAULT NULL COMMENT '人员规模',
  `company_nature` varchar(30) DEFAULT NULL COMMENT '企业性质',
  `company_profile` varchar(1024) DEFAULT NULL COMMENT '公司简介',
  `welfare` varchar(200) DEFAULT NULL COMMENT '公司福利',
  `address_name` varchar(255) DEFAULT NULL COMMENT '地址名称',
  `address` varchar(200) DEFAULT NULL COMMENT '公司地址',
  `address_house` varchar(255) DEFAULT NULL COMMENT '门牌号',
  `longitude` varchar(30) DEFAULT NULL COMMENT '地址经度',
  `latitude` varchar(30) DEFAULT NULL COMMENT '地址纬度',
  `start_time` varchar(10) DEFAULT NULL COMMENT '工作开始时间',
  `end_time` varchar(10) DEFAULT NULL COMMENT '工作结束时间',
  `rest_time` varchar(30) DEFAULT NULL COMMENT '休息时间',
  `work_overtime` varchar(20) DEFAULT NULL COMMENT '加班情况',
  `album` varchar(2048) DEFAULT NULL COMMENT '公司相册，逗号分隔',
  `business_license` varchar(255) DEFAULT NULL COMMENT '营业执照',
  `real_name` varchar(30) DEFAULT NULL COMMENT '企业名称',
  `legal_person` varchar(30) DEFAULT NULL COMMENT '法人名称',
  `identity` varchar(30) DEFAULT NULL COMMENT '营业执照号',
  `verify_status` int(3) DEFAULT NULL COMMENT '认证状态：0-默认，1-待审核，2-审核失败，3-审核通过',
  `refuse_reason` varchar(100) DEFAULT NULL COMMENT '失败原因',
  `add_auth_time` datetime DEFAULT NULL COMMENT '提交认证时间',
  `auth_date` datetime DEFAULT NULL COMMENT '审核时间',
  `browse_number` int(10) DEFAULT NULL COMMENT '浏览数量',
  `city` varchar(50) DEFAULT NULL COMMENT '县级城市名称',
  `citycode` varchar(50) DEFAULT NULL COMMENT '县级城市编码',
  `pcity` varchar(50) DEFAULT NULL COMMENT '市级城市名称',
  `pcitycode` varchar(50) DEFAULT NULL COMMENT '市级城市编码',
  `sort` int(10) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) CHARACTER SET utf8 DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(10) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(3) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公司信息表';

-- ----------------------------
-- Records of rms_company
-- ----------------------------

-- ----------------------------
-- Table structure for rms_company_position
-- ----------------------------
DROP TABLE IF EXISTS `rms_company_position`;
CREATE TABLE `rms_company_position` (
  `id` varchar(50) NOT NULL,
  `position_type` int(3) DEFAULT '1' COMMENT '类型：1-普通职位，2-灵活用工，3-共享用工',
  `if_parttime` int(3) DEFAULT NULL COMMENT '是否兼职：1-兼职，0-全职',
  `company_id` varchar(50) DEFAULT NULL COMMENT '公司ID',
  `member_id` varchar(50) DEFAULT NULL COMMENT '用户id',
  `post_id` varchar(50) DEFAULT NULL COMMENT '名称ID',
  `post_name` varchar(30) DEFAULT NULL COMMENT '职位名称',
  `descr` text COMMENT '职位描述',
  `address_name` varchar(255) DEFAULT NULL COMMENT '地址名称',
  `address_house` varchar(255) DEFAULT NULL COMMENT '门牌号',
  `address` varchar(200) DEFAULT NULL COMMENT '工作地点',
  `longitude` varchar(30) DEFAULT NULL COMMENT '地点经度',
  `latitude` varchar(30) DEFAULT NULL COMMENT '地点纬度',
  `exp_require` varchar(30) DEFAULT NULL COMMENT '经验要求',
  `min_education` varchar(30) DEFAULT NULL COMMENT '最低学历',
  `salary_low` varchar(10) DEFAULT NULL COMMENT '薪资范围',
  `salary_up` varchar(10) DEFAULT NULL COMMENT '薪资范围',
  `salary_month` int(10) DEFAULT NULL COMMENT '薪资月份',
  `salary` varchar(30) DEFAULT NULL COMMENT '薪资范围',
  `unit` varchar(255) DEFAULT NULL COMMENT '薪资单位，兼职，元/时，元/天，元/周，元/月',
  `unit_money` decimal(10,2) DEFAULT NULL COMMENT '兼职，薪资单价',
  `bonus` varchar(255) DEFAULT NULL COMMENT '奖金绩效',
  `settlement_type` int(3) DEFAULT NULL COMMENT '结算方式，兼职，日结、周结、月结、完工结',
  `recruits_number` int(11) DEFAULT NULL COMMENT '招聘人数',
  `part_date` varchar(100) DEFAULT NULL COMMENT '兼职工作日',
  `part_time` varchar(100) DEFAULT NULL COMMENT '兼职时间',
  `phone` varchar(11) DEFAULT NULL COMMENT '联系电话',
  `skill` varchar(200) DEFAULT NULL COMMENT '技能要求',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `work_days` int(10) DEFAULT NULL COMMENT '工作天数',
  `share_number` int(10) DEFAULT '0' COMMENT '共享人数',
  `share_money` decimal(10,2) DEFAULT '0.00' COMMENT '分享佣金',
  `browse_number` int(10) DEFAULT '0' COMMENT '浏览数量',
