-- ----------------------------
-- Table structure for ums_chat_history
-- ----------------------------
DROP TABLE IF EXISTS `ums_chat_history`;
CREATE TABLE `ums_chat_history` (
  `id` varchar(50) NOT NULL COMMENT '消息id',
  `rest_host` varchar(100) DEFAULT NULL COMMENT '区域',
  `app_key` varchar(100) DEFAULT NULL COMMENT 'common key',
  `user_a_id` varchar(30) DEFAULT NULL COMMENT '私聊A方',
  `user_b_id` varchar(30) DEFAULT NULL COMMENT '私聊B方',
  `group_id` varchar(30) DEFAULT NULL COMMENT '群聊ID',
  `position_id` varchar(30) DEFAULT NULL COMMENT '岗位ID',
  `type` varchar(30) DEFAULT NULL COMMENT '类型：text、audio、image、video',
  `message_id` varchar(100) DEFAULT NULL COMMENT '消息ID',
  `sender_id` varchar(30) DEFAULT NULL COMMENT '发送者ID',
  `receiver_id` varchar(30) DEFAULT NULL COMMENT '接收者ID',
  `send_time` date DEFAULT NULL COMMENT '发送时间',
  `texts` varchar(512) DEFAULT NULL COMMENT '文本内容',
  `name` varchar(200) DEFAULT NULL COMMENT '名称，针对非文本',
  `content_type` varchar(100) DEFAULT NULL COMMENT '内容类型：audio/m4a,image/jpeg,video/mp4等',
  `url` varchar(512) DEFAULT NULL COMMENT 'url地址，图片或者视频地址',
  `cover_url` varchar(512) DEFAULT NULL COMMENT '封面地址,针对视频',
  `duration` double(12,2) DEFAULT NULL COMMENT '时长，视频、音频',
  `width` int(10) DEFAULT NULL COMMENT '宽度',
  `height` int(10) DEFAULT NULL COMMENT '高度',
  `size` double(12,0) DEFAULT NULL COMMENT '大小',
  `payload` text COMMENT '内容信息',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `status` int(3) DEFAULT NULL COMMENT '启用状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` date DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` date DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(10) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(3) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='聊天记录表';

