  `member_id` varchar(50) DEFAULT NULL COMMENT '会员ID',
  `job_type` int(3) DEFAULT NULL COMMENT '求职类型：0-全职，1-兼职',
  `work_city` varchar(20) DEFAULT NULL COMMENT '工作城市',
  `post_id` int(19) DEFAULT NULL COMMENT '期望职位',
  `post_name` varchar(30) DEFAULT NULL COMMENT '职位名称',
  `industry_id` varchar(200) DEFAULT NULL COMMENT '期望行业',
  `industry_name` varchar(100) DEFAULT NULL COMMENT '行业名称',
  `salary_low` varchar(20) DEFAULT NULL COMMENT '薪资要求',
  `salary_up` varchar(20) DEFAULT NULL COMMENT '薪资要求',
  `expect_salary` varchar(30) DEFAULT NULL COMMENT '期望薪资，如10-20K',
  `status` varchar(3) DEFAULT NULL COMMENT '是否启用',
  `sort` int(10) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) CHARACTER SET utf8 DEFAULT NULL COMMENT '所属部门编码',
  `tenant_id` int(10) DEFAULT NULL COMMENT 'tenantId',
  `del_flag` int(3) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='个人简历表';

