INSERT INTO `sys_log` VALUES ('1580055989544787970', '2', '题目信息-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.sub.controller.SubTitleController.add()', null, '[{\"sort\":1,\"subAnswerList\":[{\"answer\":\"B\",\"createBy\":\"admin\",\"createTime\":1665549678564,\"id\":\"1580055989456707585\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580055989364432898\"}],\"subType\":1,\"title\":\"李白有诗“吾爱孟夫子，风流天下闻”，“孟夫子”指的是____。\"}]', null, '51', null, '2022-10-12 12:41:19', null, null, null);
INSERT INTO `sys_log` VALUES ('1580056477182959618', '2', '题目信息-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.sub.controller.SubTitleController.add()', null, '[{\"sort\":1,\"subAnswerList\":[{\"analysis\":\"《尚书》又称《书》、《书经》，是我国第一部上古历史文件和部分追述古代事迹著作的汇编。《尚书》分为《虞书》、《夏书》、《商书》、《周书》。战国时期总称《书》，汉代改称《尚书》，即“上古之书”，是儒家五经之一。《尚书》是中国最古老的皇室文集，是中国第一部上古历史文件和部分追述古代事迹著作的汇编，它保存了商周特别是西周初期的一些重要史料。《尚书》相传由孔子编撰而成，但有些篇目是后来儒家补充进去的托古作品。\",\"answer\":\"B\",\"createBy\":\"admin\",\"createTime\":1665549794842,\"id\":\"1580056477157793794\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056477090684929\"}],\"subType\":1,\"title\":\"《尚书》原来称为《书》，称《尚书》始于____。\"}]', null, '24', null, '2022-10-12 12:43:15', null, null, null);
INSERT INTO `sys_log` VALUES ('1580056774278094850', '2', '题目信息-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.sub.controller.SubTitleController.add()', null, '[{\"subAnswerList\":[{\"analysis\":\"经常有人用“厚脸皮”这个词来形容厚颜无耻的人。那么人的脸皮究竟有多厚呢？人的脸皮由表皮、真皮和皮下组织组成。表皮+真皮+皮下组织的皮肤厚度约2-3毫米之间。所以我们的脸皮并不厚。10毫米就是1厘米了，很难想像脸皮厚1厘米。\",\"answer\":\"A\",\"createBy\":\"admin\",\"createTime\":1665549865672,\"id\":\"1580056774244540418\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056774194208769\"}],\"subSelectList\":[{\"content\":\"2-3\",\"createBy\":\"admin\",\"createTime\":1665549865666,\"id\":\"1580056774219374594\",\"serialNo\":\"A\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056774194208769\"},{\"content\":\"10-12\",\"createBy\":\"admin\",\"createTime\":1665549865670,\"id\":\"1580056774236151809\",\"serialNo\":\"B\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056774194208769\"}],\"subType\":1,\"title\":\"大部分人类脸皮的厚度约为____毫米。\"}]', null, '17', null, '2022-10-12 12:44:26', null, null, null);
INSERT INTO `sys_log` VALUES ('1580056940670328834', '2', '题目信息-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.sub.controller.SubTitleController.add()', null, '[{\"subAnswerList\":[{\"analysis\":\"人类的皮肤可以呼吸，但呼吸量极小，皮肤吸收的氧气量仅为肺的1%，不足以供应人体正常的新陈代谢所需，所以人不能生活在水里。但只有正常皮肤呼吸的人，皮肤才会通透有光泽。\",\"answer\":\"A\",\"createBy\":\"admin\",\"createTime\":1665549905347,\"id\":\"1580056940653551618\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056940619997186\"}],\"subSelectList\":[{\"content\":\"能\",\"createBy\":\"admin\",\"createTime\":1665549905343,\"id\":\"1580056940636774402\",\"serialNo\":\"A\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056940619997186\"},{\"content\":\"不能\",\"createBy\":\"admin\",\"createTime\":1665549905345,\"id\":\"1580056940645163009\",\"serialNo\":\"B\",\"sysOrgCode\":\"A01\",\"titleId\":\"1580056940619997186\"}],\"subType\":1,\"title\":\"人的皮肤是____进行呼吸的。\"}]', null, '13', null, '2022-10-12 12:45:05', null, null, null);
