INSERT INTO `sys_log` VALUES ('1580744906254254081', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县168乡道附近\",\"antiepidemicPolicy\":\"无\",\"area\":\"大余县\",\"businessTime\":\"周二至周日9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-7237989\",\"content\":\"<p>梅岭三章纪念馆位于南安镇建设村梅山红色文化景区内，所处位置是南方红军三年游击战争期间中共中央分局、中央政府办事处所在地，作为主要领导人之一的陈毅在梅山斋坑被围时，写下了气壮山河的《梅岭三章》，大余人民为保护珍贵的革命旧址和文物，故建馆加以纪念。</p>\\n<p>陈毅元帅诗词专题展览分为四个部分：第一部分为序厅；第二部分为创业艰难百战多；第三部分为大庾岭上暮天低；第四部分为弥天烽火举红旗；第五部分为团结抗日下山来。陈展突出展示陈毅元帅指挥游击战争的坚定信仰和丰功伟绩，游击战士百折不挠、敢于战胜一切敌人的英雄气概以及人民群众支援游击战士和游击区建设的生动事迹。</p>\\n<p>展览围绕大余老区这一红色地域特色，将搜集的近51件文物展示，辅之以图片、文献、模型、仿真复制、3D投影、幻影成像等现代数码技术手段，演绎、再现了赣粤边游击战争波澜壮阔的历史场景，使历史感、艺术感、现代感结合在一起。同时，展厅内还借助了油画、国画、浮雕、版画、蜡像、雕塑等其他艺术形式，丰富了展出形式、提升了展示效果的艺术性，真实再现了游击战争的光辉历史，弘扬坚定信念、百折不饶、艰苦奋斗的革命精神。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信截图_20221013161345_1665648847672.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580472601515122690\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.347963\",\"longitude\":\"114.387041\",\"name\":\"梅岭三章纪念馆\",\"sort\":10,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665713929122,\"video\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/梅岭三章纪念馆宣传视频_1665648942419.mp4\",\"viewCount\":2}]', null, '6', null, '2022-10-14 10:18:49', null, null, null);
INSERT INTO `sys_log` VALUES ('1580744987950907393', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区厚德路22号发达集团公司(门卫室)\",\"antiepidemicPolicy\":\" 省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"章贡区\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"11111111111\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d441ab4c1fbd089249b5ca9cf7aba06_1665467337935.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711017004015617\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.854993\",\"longitude\":\"114.952365\",\"name\":\"福寿沟博物馆\",\"sort\":11,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665713948602,\"viewCount\":124}]', null, '5', null, '2022-10-14 10:19:09', null, null, null);
INSERT INTO `sys_log` VALUES ('1580745087670484994', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市会昌县223省道南100米\",\"antiepidemicPolicy\":\"    省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"会昌县\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"11111111111\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇坐落在赣州市会昌县白鹅乡的梓坑村。这是一个客家原住民的典型村落，森林竹海、田园生活，生态环境十分优美。这也是一个红色村，当年留守苏区的党政军中央机关，集中驻扎在这个村子里。村里有苏区中央军区政治部旧址（下园坝新屋）、留守苏区中央运输连旧址（上园坝李氏宗祠）、留守苏区红军供销合作社旧址（上园坝）、留守苏区中央总供给部旧址（溪背新屋）、留守苏区中央兵工厂旧址（大塘湖林氏宗祠）、留守苏区中央国家银行旧址（白沙园）等6处列入赣州市第二批不可移动文物保护名录，2018年3月被列为省级文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇由北京和君集团发起投资和建设，是江西省政府公布的江西省重点投资项目，也是江西省政府审定的省级特色小镇。2021年，小镇创办和君职业学院，这是全国第一所办在革命老区村子里的大学。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209281715163_1665467535715.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711919324635137\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.838229\",\"longitude\":\"115.602885\",\"name\":\"赣州市红色文化研究会（和君小镇）\",\"sort\":12,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665713972375,\"viewCount\":2}]', null, '6', null, '2022-10-14 10:19:32', null, null, null);
