INSERT INTO `sys_log` VALUES ('1580921778971820034', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市全南县陂头镇文化路与平安路交汇处\",\"antiepidemicPolicy\":\"无\",\"area\":\"全南县\",\"businessTime\":\"9:00-17:30\",\"clockCount\":0,\"clockRadius\":50,\"content\":\"<p>陂头镇新时代文明实践所位于陂头圩镇文化路与平安路交汇处，占地面积7771平方米，建筑面积2519平方米，整合原八一垦殖场文化中心、长城社区居家养老服务中心等场所，是集宣传教育、体育文艺、医疗康养、议事协商于一体的综合性邻里中心。所内功能完善，配套齐全，设有&ldquo;党建+&rdquo;乡村振兴展厅、军垦文化展厅（八一垦殖场场史馆）、知青文化展厅、廉政文化展厅、瑶族非遗传承馆等五大主题文化展厅；书香全南阅览室、科普驿站、消防体验室、舞蹈培训中心、棋牌书画室等五个文教互动阵地；日间照料中心、居家养老服务中心（孝老食堂）；早教活动中心、童心港湾室、康复理疗室等五类便民服务场所；人大代表联络站、政协委员联络工作站、人才驿站（乡贤馆）、志愿服务站、乡镇党校等五项基层工作平台；实践所内外共有30余处场所场地和功能室，可为广大群众提供理论宣讲、教育引导、志愿服务、文体培训、科学普及、移风易俗、普法宣传等形式多样的文明实践活动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/xsd_1665648187549.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580470377477038082\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.009168\",\"longitude\":\"114.589681\",\"name\":\"陂头镇新时代文明实践所\",\"sort\":7,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"无\",\"updateBy\":\"admin\",\"updateTime\":1665756098827,\"viewCount\":3}]', null, '7', null, '2022-10-14 22:01:39', null, null, null);
INSERT INTO `sys_log` VALUES ('1580921900153651201', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市瑞金市红都路龙珠路1号\",\"antiepidemicPolicy\":\"无\",\"area\":\"瑞金市\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/rjzygm_1665647805384.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468130806489090\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.873421\",\"longitude\":\"116.014385\",\"name\":\"瑞金中央革命根据地纪念馆\",\"sort\":4,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"成人票：100元/人 儿童票：50元/人 免票：低于130mm的儿童，以及年龄大于60岁的老人\",\"updateBy\":\"admin\",\"updateTime\":1665756127755,\"video\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/瑞金纪念馆推介宣传片_1665647816026.mp4\",\"viewCount\":2}]', null, '7', null, '2022-10-14 22:02:08', null, null, null);
INSERT INTO `sys_log` VALUES ('1580921989572018177', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区福寿沟博物馆旁边\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院横跨赣州老城区罗家巷、荷包塘、慈姑岭三条街，是市区现存最大的清代家族民居建筑群，大院始建于嘉庆年间（1799-1820），定型于民国初年，至今已有200年历史，为江西省文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院是清代中期至民国初年陆续建造的民居，是赣州乃至全省城区范围内现存最大的清代客家大屋，集中体现了赣南传统建筑的典型格式，是赣南一处珍贵的、人文内涵丰富的家族建筑群，是赣州古建筑的精华。&nbsp;</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院核心区已修复区域用于打造&ldquo;赣南客家文化博物馆&rdquo;。通过文字、图片、图表、文物、实物、场景再现以及现代全息等技术手段，多角度、多形式展现赣南客家人的生产生活情景。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606_1665648012232.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468610148327425\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.855513\",\"longitude\":\"114.952607\",\"name\":\"魏家大院\",\"sort\":5,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665756149077,\"viewCount\":22}]', null, '6', null, '2022-10-14 22:02:29', null, null, null);
INSERT INTO `sys_log` VALUES ('1580922059805638657', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区西津路8号\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;阳明书院，位于江西赣州郁孤台下。原名濂溪书院。阳明书院是一座研究、挖掘、传扬王阳明心学的专业书院，集藏书售书、学术研讨、国学传授、阳明生平介绍、古琴教育、古玩鉴赏、书画作品和文房用品展示推介等为一体的综合性旅游点，已被列入赣州市郁孤台历史文化街区旅游景点。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;赣州阳明书院位于明代&ldquo;阳明书院&rdquo;旧址，占地2300平米，有效房间面积1580平米，是典型的三进式客家民居。学院内设仰德堂、良知堂、知行堂、传习堂、望德亭、&ldquo;三纲八目&rdquo;茶社、思归轩、阳明精舍（书院）、阳明手迹碑林、格竹园、阳明别苑等。书院内涉及王阳明的各类藏书已达5000余册。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209301611331_1665648101579.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468987241422850\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.864054\",\"longitude\":\"114.937802\",\"name\":\"阳明书院\",\"sort\":6,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665756165821,\"viewCount\":32}]', null, '6', null, '2022-10-14 22:02:46', null, null, null);
INSERT INTO `sys_log` VALUES ('1580922111307497474', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市全南县陂头镇文化路与平安路交汇处\",\"antiepidemicPolicy\":\"无\",\"area\":\"全南县\",\"businessTime\":\"9:00-17:30\",\"clockCount\":0,\"clockRadius\":50,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;陂头镇新时代文明实践所位于陂头圩镇文化路与平安路交汇处，占地面积7771平方米，建筑面积2519平方米，整合原八一垦殖场文化中心、长城社区居家养老服务中心等场所，是集宣传教育、体育文艺、医疗康养、议事协商于一体的综合性邻里中心。所内功能完善，配套齐全，设有&ldquo;党建+&rdquo;乡村振兴展厅、军垦文化展厅（八一垦殖场场史馆）、知青文化展厅、廉政文化展厅、瑶族非遗传承馆等五大主题文化展厅；书香全南阅览室、科普驿站、消防体验室、舞蹈培训中心、棋牌书画室等五个文教互动阵地；日间照料中心、居家养老服务中心（孝老食堂）；早教活动中心、童心港湾室、康复理疗室等五类便民服务场所；人大代表联络站、政协委员联络工作站、人才驿站（乡贤馆）、志愿服务站、乡镇党校等五项基层工作平台；实践所内外共有30余处场所场地和功能室，可为广大群众提供理论宣讲、教育引导、志愿服务、文体培训、科学普及、移风易俗、普法宣传等形式多样的文明实践活动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/xsd_1665648187549.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580470377477038082\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.009168\",\"longitude\":\"114.589681\",\"name\":\"陂头镇新时代文明实践所\",\"sort\":7,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"无\",\"updateBy\":\"admin\",\"updateTime\":1665756178101,\"viewCount\":3}]', null, '5', null, '2022-10-14 22:02:58', null, null, null);
INSERT INTO `sys_log` VALUES ('1580922238151639042', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县大余县南安镇东山村菜园里(原大余县第三医院)\",\"antiepidemicPolicy\":\"无\",\"area\":\"大余县\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-8721619\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; 大余县博物馆成立于上世纪七十年代，经国家文物局审批备案，是一座集文物收藏、历史研究、社会教育、旅游观光为一体的综合性博物馆。馆藏文物2000余件，占地面积7.5亩，建筑面积3400.53㎡，设基本陈列展1个，临时展5个，为江西省博物馆协会理事单位。大余县博物馆通过文物陈展，让观众记得历史沧桑，看得见岁月印痕，护得住文化根脉，让大余的文化遗产焕发出更加耀眼的光彩。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/dybwg_1665648705488.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580471538695266305\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.388169\",\"longitude\":\"114.368082\",\"name\":\"大余县博物馆\",\"sort\":9,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665756208341,\"viewCount\":3}]', null, '6', null, '2022-10-14 22:03:28', null, null, null);
INSERT INTO `sys_log` VALUES ('1580922305738653698', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县168乡道附近\",\"antiepidemicPolicy\":\"无\",\"area\":\"大余县\",\"businessTime\":\"周二至周日9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-7237989\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信截图_20221013161345_1665648847672.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580472601515122690\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.347963\",\"longitude\":\"114.387041\",\"name\":\"梅岭三章纪念馆\",\"sort\":10,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665756224455,\"video\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/梅岭三章纪念馆宣传视频_1665648942419.mp4\",\"viewCount\":2}]', null, '8', null, '2022-10-14 22:03:44', null, null, null);
INSERT INTO `sys_log` VALUES ('1580922378799235073', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区厚德路22号发达集团公司(门卫室)\",\"antiepidemicPolicy\":\" 省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"章贡区\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"11111111111\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d441ab4c1fbd089249b5ca9cf7aba06_1665467337935.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711017004015617\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.854993\",\"longitude\":\"114.952365\",\"name\":\"福寿沟博物馆\",\"sort\":11,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665756241876,\"viewCount\":124}]', null, '5', null, '2022-10-14 22:04:02', null, null, null);
INSERT INTO `sys_log` VALUES ('1580922427809677314', '2', '基地信息-编辑', '3', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市会昌县223省道南100米\",\"antiepidemicPolicy\":\"    省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"会昌县\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"11111111111\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇坐落在赣州市会昌县白鹅乡的梓坑村。这是一个客家原住民的典型村落，森林竹海、田园生活，生态环境十分优美。这也是一个红色村，当年留守苏区的党政军中央机关，集中驻扎在这个村子里。村里有苏区中央军区政治部旧址（下园坝新屋）、留守苏区中央运输连旧址（上园坝李氏宗祠）、留守苏区红军供销合作社旧址（上园坝）、留守苏区中央总供给部旧址（溪背新屋）、留守苏区中央兵工厂旧址（大塘湖林氏宗祠）、留守苏区中央国家银行旧址（白沙园）等6处列入赣州市第二批不可移动文物保护名录，2018年3月被列为省级文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇由北京和君集团发起投资和建设，是江西省政府公布的江西省重点投资项目，也是江西省政府审定的省级特色小镇。2021年，小镇创办和君职业学院，这是全国第一所办在革命老区村子里的大学。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209281715163_1665467535715.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711919324635137\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.838229\",\"longitude\":\"115.602885\",\"name\":\"赣州市红色文化研究会（和君小镇）\",\"sort\":12,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665756253561,\"viewCount\":2}]', null, '4', null, '2022-10-14 22:04:14', null, null, null);
