INSERT INTO `sys_log` VALUES ('1581586279122952193', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区福寿沟博物馆旁边\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606(1)_1665914513683.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30170758(1)_1665914512963.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_20220930163657_1665914510519.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_20220930171035_1665914511208.jpg\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院横跨赣州老城区罗家巷、荷包塘、慈姑岭三条街，是市区现存最大的清代家族民居建筑群，大院始建于嘉庆年间（1799-1820），定型于民国初年，至今已有200年历史，为江西省文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院是清代中期至民国初年陆续建造的民居，是赣州乃至全省城区范围内现存最大的清代客家大屋，集中体现了赣南传统建筑的典型格式，是赣南一处珍贵的、人文内涵丰富的家族建筑群，是赣州古建筑的精华。&nbsp;</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院核心区已修复区域用于打造&ldquo;赣南客家文化博物馆&rdquo;。通过文字、图片、图表、文物、实物、场景再现以及现代全息等技术手段，多角度、多形式展现赣南客家人的生产生活情景。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606_1665648012232.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468610148327425\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.855513\",\"longitude\":\"114.952607\",\"name\":\"魏家大院\",\"sort\":5,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665914528047,\"viewCount\":22}]', null, '6', null, '2022-10-16 18:02:08', null, null, null);
INSERT INTO `sys_log` VALUES ('1581587713952407553', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区西津路8号\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;阳明书院，位于江西赣州郁孤台下。原名濂溪书院。阳明书院是一座研究、挖掘、传扬王阳明心学的专业书院，集藏书售书、学术研讨、国学传授、阳明生平介绍、古琴教育、古玩鉴赏、书画作品和文房用品展示推介等为一体的综合性旅游点，已被列入赣州市郁孤台历史文化街区旅游景点。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;赣州阳明书院位于明代&ldquo;阳明书院&rdquo;旧址，占地2300平米，有效房间面积1580平米，是典型的三进式客家民居。学院内设仰德堂、良知堂、知行堂、传习堂、望德亭、&ldquo;三纲八目&rdquo;茶社、思归轩、阳明精舍（书院）、阳明手迹碑林、格竹园、阳明别苑等。书院内涉及王阳明的各类藏书已达5000余册。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209301611331_1665648101579.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468987241422850\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.864054\",\"longitude\":\"114.937802\",\"name\":\"阳明书院\",\"sort\":6,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665914870138,\"viewCount\":33}]', null, '6', null, '2022-10-16 18:07:50', null, null, null);
INSERT INTO `sys_log` VALUES ('1581587788627795969', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区西津路8号\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;阳明书院，位于江西赣州郁孤台下。原名濂溪书院。阳明书院是一座研究、挖掘、传扬王阳明心学的专业书院，集藏书售书、学术研讨、国学传授、阳明生平介绍、古琴教育、古玩鉴赏、书画作品和文房用品展示推介等为一体的综合性旅游点，已被列入赣州市郁孤台历史文化街区旅游景点。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;赣州阳明书院位于明代&ldquo;阳明书院&rdquo;旧址，占地2300平米，有效房间面积1580平米，是典型的三进式客家民居。学院内设仰德堂、良知堂、知行堂、传习堂、望德亭、&ldquo;三纲八目&rdquo;茶社、思归轩、阳明精舍（书院）、阳明手迹碑林、格竹园、阳明别苑等。书院内涉及王阳明的各类藏书已达5000余册。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209301611331_1665648101579.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468987241422850\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.864054\",\"longitude\":\"114.937802\",\"name\":\"阳明书院\",\"sort\":6,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665914887942,\"viewCount\":33}]', null, '5', null, '2022-10-16 18:08:08', null, null, null);
INSERT INTO `sys_log` VALUES ('1581588220985040898', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市全南县陂头镇文化路与平安路交汇处\",\"antiepidemicPolicy\":\"无\",\"area\":\"全南县\",\"businessTime\":\"9:00-17:30\",\"clockCount\":0,\"clockRadius\":50,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;陂头镇新时代文明实践所位于陂头圩镇文化路与平安路交汇处，占地面积7771平方米，建筑面积2519平方米，整合原八一垦殖场文化中心、长城社区居家养老服务中心等场所，是集宣传教育、体育文艺、医疗康养、议事协商于一体的综合性邻里中心。所内功能完善，配套齐全，设有&ldquo;党建+&rdquo;乡村振兴展厅、军垦文化展厅（八一垦殖场场史馆）、知青文化展厅、廉政文化展厅、瑶族非遗传承馆等五大主题文化展厅；书香全南阅览室、科普驿站、消防体验室、舞蹈培训中心、棋牌书画室等五个文教互动阵地；日间照料中心、居家养老服务中心（孝老食堂）；早教活动中心、童心港湾室、康复理疗室等五类便民服务场所；人大代表联络站、政协委员联络工作站、人才驿站（乡贤馆）、志愿服务站、乡镇党校等五项基层工作平台；实践所内外共有30余处场所场地和功能室，可为广大群众提供理论宣讲、教育引导、志愿服务、文体培训、科学普及、移风易俗、普法宣传等形式多样的文明实践活动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/xsd_1665648187549.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580470377477038082\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.009168\",\"longitude\":\"114.589681\",\"name\":\"陂头镇新时代文明实践所\",\"sort\":7,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"无\",\"updateBy\":\"admin\",\"updateTime\":1665914991023,\"viewCount\":4}]', null, '6', null, '2022-10-16 18:09:51', null, null, null);
