INSERT INTO `sys_log` VALUES ('1581590389213716481', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县大余县南安镇东山村菜园里(原大余县第三医院)\",\"antiepidemicPolicy\":\"无\",\"area\":\"大余县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/dybwg_1665915469847.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2acbf4e10b42ab3cfdf3f4c207b19bd_1665915494701.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d9b05796c3ac944154a36744efb330a_1665915486071.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/ed9acc760b40a99a3d10f0819185698_1665915484525.jpg\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-8721619\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; 大余县博物馆成立于上世纪七十年代，经国家文物局审批备案，是一座集文物收藏、历史研究、社会教育、旅游观光为一体的综合性博物馆。馆藏文物2000余件，占地面积7.5亩，建筑面积3400.53㎡，设基本陈列展1个，临时展5个，为江西省博物馆协会理事单位。大余县博物馆通过文物陈展，让观众记得历史沧桑，看得见岁月印痕，护得住文化根脉，让大余的文化遗产焕发出更加耀眼的光彩。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/dybwg_1665648705488.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580471538695266305\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.388169\",\"longitude\":\"114.368082\",\"name\":\"大余县博物馆\",\"sort\":9,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665915507967,\"viewCount\":5}]', null, '8', null, '2022-10-16 18:18:28', null, null, null);
INSERT INTO `sys_log` VALUES ('1581591102455111682', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县168乡道附近\",\"antiepidemicPolicy\":\"无\",\"area\":\"大余县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/改4_1665915655127.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/_Y4W7947_1665915669901.JPG,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/_Y4W7988_1665915669944.JPG,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/IMG_6248_1665915669940.JPG,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/改1_1665915672325.jpg\",\"businessTime\":\"周二至周日9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-7237989\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信截图_20221013161345_1665648847672.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580472601515122690\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.347963\",\"longitude\":\"114.387041\",\"name\":\"梅岭三章纪念馆\",\"sort\":10,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665915678020,\"video\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/梅岭三章纪念馆宣传视频_1665648942419.mp4\",\"viewCount\":4}]', null, '6', null, '2022-10-16 18:21:18', null, null, null);
INSERT INTO `sys_log` VALUES ('1581591427954073601', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区厚德路22号发达集团公司(门卫室)\",\"antiepidemicPolicy\":\" 省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"章贡区\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"11111111111\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d441ab4c1fbd089249b5ca9cf7aba06_1665467337935.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711017004015617\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.854993\",\"longitude\":\"114.952365\",\"name\":\"福寿沟博物馆\",\"sort\":11,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665915755624,\"viewCount\":126}]', null, '6', null, '2022-10-16 18:22:36', null, null, null);
INSERT INTO `sys_log` VALUES ('1581591653943173121', '2', '基地信息-编辑', '3', 'admin', '管理员', '183.218.69.10', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市会昌县223省道南100米\",\"antiepidemicPolicy\":\"    省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"会昌县\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"11111111111\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇坐落在赣州市会昌县白鹅乡的梓坑村。这是一个客家原住民的典型村落，森林竹海、田园生活，生态环境十分优美。这也是一个红色村，当年留守苏区的党政军中央机关，集中驻扎在这个村子里。村里有苏区中央军区政治部旧址（下园坝新屋）、留守苏区中央运输连旧址（上园坝李氏宗祠）、留守苏区红军供销合作社旧址（上园坝）、留守苏区中央总供给部旧址（溪背新屋）、留守苏区中央兵工厂旧址（大塘湖林氏宗祠）、留守苏区中央国家银行旧址（白沙园）等6处列入赣州市第二批不可移动文物保护名录，2018年3月被列为省级文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇由北京和君集团发起投资和建设，是江西省政府公布的江西省重点投资项目，也是江西省政府审定的省级特色小镇。2021年，小镇创办和君职业学院，这是全国第一所办在革命老区村子里的大学。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209281715163_1665467535715.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711919324635137\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.838229\",\"longitude\":\"115.602885\",\"name\":\"赣州市红色文化研究会（和君小镇）\",\"sort\":12,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"admin\",\"updateTime\":1665915809501,\"viewCount\":3}]', null, '9', null, '2022-10-16 18:23:30', null, null, null);
