INSERT INTO `sys_log` VALUES ('1582921615170199553', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市全南县陂头镇416乡道与星光路交叉口北160米\",\"antiepidemicPolicy\":\"无\",\"area\":\"全南县\",\"businessTime\":\"9：00-12：00，15：00-17：30，19：00-20：00，周一闭所\",\"clockCount\":0,\"clockRadius\":50,\"contactNumber\":\"杨娟18879788535\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。陂头镇新时代文明实践所位于陂头圩镇文化路与平安路交汇处，占地面积7771平方米，建筑面积2519平方米，整合原八一垦殖场文化中心、长城社区居家养老服务中心等场所，是集宣传教育、体育文艺、医疗康养、议事协商于一体的综合性邻里中心。所内功能完善，配套齐全，设有&ldquo;党建+&rdquo;乡村振兴展厅、军垦文化展厅（八一垦殖场场史馆）、知青文化展厅、廉政文化展厅、瑶族非遗传承馆等五大主题文化展厅；书香全南阅览室、科普驿站、消防体验室、舞蹈培训中心、棋牌书画室等五个文教互动阵地；日间照料中心、居家养老服务中心（孝老食堂）；早教活动中心、童心港湾室、康复理疗室等五类便民服务场所；人大代表联络站、政协委员联络工作站、人才驿站（乡贤馆）、志愿服务站、乡镇党校等五项基层工作平台；实践所内外共有30余处场所场地和功能室，可为广大群众提供理论宣讲、教育引导、志愿服务、文体培训、科学普及、移风易俗、普法宣传等形式多样的文明实践活动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/xsd_1665648187549.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580470377477038082\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.009168\",\"longitude\":\"114.589681\",\"name\":\"陂头镇新时代文明实践所\",\"sort\":7,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"无\",\"updateBy\":\"test\",\"updateTime\":1666232896967,\"viewCount\":6}]', null, '8', null, '2022-10-20 10:28:17', null, null, null);
