INSERT INTO `sys_log` VALUES ('1582933112768290818', '2', '基地信息-编辑', '3', 'test', '测试', '117.136.123.171', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区厚德路22号\",\"antiepidemicPolicy\":\"省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"章贡区\",\"businessTime\":\"9:00-16:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-7317081\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d441ab4c1fbd089249b5ca9cf7aba06_1665467337935.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711017004015617\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.854993\",\"longitude\":\"114.952365\",\"name\":\"福寿沟博物馆\",\"sort\":11,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666235638209,\"viewCount\":134}]', null, '7', null, '2022-10-20 11:13:58', null, null, null);
INSERT INTO `sys_log` VALUES ('1582933417769689089', '2', '基地信息-编辑', '3', 'test', '测试', '117.136.123.171', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市会昌县223省道南100米\",\"antiepidemicPolicy\":\"    省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"会昌县\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。和君小镇坐落在赣州市会昌县白鹅乡的梓坑村。这是一个客家原住民的典型村落，森林竹海、田园生活，生态环境十分优美。这也是一个红色村，当年留守苏区的党政军中央机关，集中驻扎在这个村子里。村里有苏区中央军区政治部旧址（下园坝新屋）、留守苏区中央运输连旧址（上园坝李氏宗祠）、留守苏区红军供销合作社旧址（上园坝）、留守苏区中央总供给部旧址（溪背新屋）、留守苏区中央兵工厂旧址（大塘湖林氏宗祠）、留守苏区中央国家银行旧址（白沙园）等6处列入赣州市第二批不可移动文物保护名录，2018年3月被列为省级文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇由北京和君集团发起投资和建设，是江西省政府公布的江西省重点投资项目，也是江西省政府审定的省级特色小镇。2021年，小镇创办和君职业学院，这是全国第一所办在革命老区村子里的大学。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209281715163_1665467535715.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711919324635137\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.838229\",\"longitude\":\"115.602885\",\"name\":\"赣州市红色文化研究会（和君小镇）\",\"sort\":12,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666235710913,\"viewCount\":6}]', null, '21', null, '2022-10-20 11:15:11', null, null, null);
