INSERT INTO `sys_log` VALUES ('1582961496009334785', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市章贡区水南街道梅州路3-11号\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"全天候开放，8:30-12:00、14:30-18:00有讲解\",\"clockRadius\":200,\"contactNumber\":\"15970000991\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。上堡乡水稻科普基地位于竹溪村罗家组，毗邻万长山景区和上堡梯田景区木梓排板块的中间地带，项目占地面积110亩，总投资566万元，紧扣农业观光、稻作文化、科普教育主题，划分为7个区种植了101个水稻品种，布设了游步道、打谷场、科普长廊、水稻迷宫、观景平台、图案稻田、农耕体验区等内容，上堡乡水稻科普基地目前是国内最齐全、最丰富和最具特质的水稻种质资源圃。这也是全省第一个集&ldquo;研学+科普+农旅&rdquo;为一体的特色水稻科普基地，秉承&ldquo;传播稻作知识，弘扬农耕文化&rdquo;为宗旨，在木栈道两旁放置了二十四节气与农事谚语牌，带您领略古人智慧，促进粮食丰产增收，稳住&ldquo;米袋子&rdquo;。水稻博览园的打造既丰富了上堡的旅游业态，又策应了县委&ldquo;工业强县、生态富民、文旅融合&rdquo;的发展战略，是全面乡村振兴的一个缩影。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/828880268059320b36f8e997f17c6da_1666241596461.jpg\",\"createBy\":\"test\",\"createTime\":1666242405302,\"id\":\"1582961495984168961\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.83\",\"longitude\":\"114.93\",\"name\":\"上堡乡水稻科普基地\",\"sort\":18,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '6', null, '2022-10-20 13:06:45', null, null, null);
INSERT INTO `sys_log` VALUES ('1582963507169714178', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市信丰县油山镇滴水垄饭店西南侧150米\",\"antiepidemicPolicy\":\"无\",\"area\":\"信丰县\",\"businessTime\":\"24小时\",\"clockRadius\":100,\"contactNumber\":\"吴春妹13870786958\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。1935年3月底,中央分局书记、中央军区司令员兼政委项英,中央分局委员、中央政府办事处主任陈毅到达以油山为中心的赣粤边地区，在这里领导了坚苦卓绝的三年游击战争。赣南游击词主题园位于中央红色美丽村庄信丰县油山镇坑口村，规划面积约2600亩，核心区约70亩，总投资约2.9亿元，目前已经建成以赣粤边三年游击战争为历史背景的红色生态文化旅游景点，也是赣州市红色旅游区全域旅游专项规划的一个重要组成部分。主要建设有红军广场、赣南游击词历史陈列馆、新四军队发祥地历史陈列馆、赣粤边三年游击战争纪念碑、赣南游击词文化墙、游击密道、项英宿营处、赣南特委机关旧址、广东省委旧址等景点和游客服务区、油山干部学院、旅游公路、停车场等附属设施，是以红色为魂、山水为景、乡村为辅的集纪念、传承、体验、休闲、康养、红色研学等功能于一体的红色生态文化旅游基地。目前，已经成为我市开展传承红色基因现场教学的重要课堂，是广大党员、干部、群众和青少年接受革命传统教育的爱国主义教育基地，2021年3月，被命名为信丰县爱国主义教育基地。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/微信图片_20220921164105_1666242591998.jpg\",\"createBy\":\"test\",\"createTime\":1666242884800,\"id\":\"1582963507140354049\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.405787\",\"longitude\":\"114.655193\",\"name\":\"赣南游击词主题园\",\"sort\":19,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '7', null, '2022-10-20 13:14:45', null, null, null);
