INSERT INTO `sys_log` VALUES ('1582986067286548482', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市赣县区双龙大道16号\",\"antiepidemicPolicy\":\"无\",\"area\":\"赣县区\",\"businessTime\":\"周一至周五，9:00-12:00，15:00-17:00\",\"clockRadius\":100,\"contactNumber\":\"18178998039\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; 该基地为赣州市社科普及基地。赣县区人民法院青少年法治教育基地设在审判大楼四楼，占地面积达400余平方米，融少年审判、预防犯罪、教育挽救等一体。基地分为视听区、展示区两部分，展示区设有前言、警示、感化、教育、预防和纪实六个篇章，搜集制作了大量的典型案例、图片资料、实物样品等，努力为全区青少年提供一个思政学习和体验式教育服务平台。此外，该院还成立以女法官为主体的青少年法治教育宣讲团，通过&ldquo;零距离&rdquo;体验庭审、参加主题班会、法治课堂、在线答疑等方式，开展法治宣传教育活动，营造学法尊法守法用法的法治氛围，得到省、市、区领导的充分肯定，获《人民法院报》《江西日报》等主流媒体关注。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/法院全貌_1666248046047.jpg\",\"createBy\":\"test\",\"createTime\":1666248263551,\"id\":\"1582986067261382657\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.867596\",\"longitude\":\"115.015557\",\"name\":\"赣县区人民法院青少年法治教育基地\",\"sort\":27,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '6', null, '2022-10-20 14:44:24', null, null, null);
