INSERT INTO `sys_log` VALUES ('1583005525388419073', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市兴国县将军大道附近\",\"antiepidemicPolicy\":\"无\",\"area\":\"兴国县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155713_1666252652205.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155618_1666252662795.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155548_1666252671045.png\",\"businessTime\":\"8:30-17:30，周一闭馆\",\"clockRadius\":100,\"contactNumber\":\"0797-5318997\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。将军园（苏园）景区位于兴国将军大道南端，占地508亩，是我县著名的&ldquo;全国爱国主义教育示范基地&rdquo;，中央党校、国防大学等众多高等院校和相关单位的教育基地，是江西省首个通过国家级旅游服务业标准化试点项目验收的红色景区。景区作为我县最大的公共游览公园，集参观学习、旅游观光、休闲娱乐于一体，布局有将军园和苏区干部好作风纪念园两园。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;将军园由将军馆、将军广场、大型群雕、国防教育广场、休闲广场、将军湖、将军岛、上将亭等组成。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;将军馆2018年被评为&ldquo;全省十大精品馆&rdquo;，建筑面积4200平方米，布展面积3090平方米，展线长530米，屋顶是红军八角帽造型，展厅和大门由镰刀、斧头形状构成，将军馆一楼为兴国籍56位开国将军生平展；二楼为兴国籍省部军级领导干部简介，利用图片、实物、文字等形式再现了兴国籍将军们的英勇事迹。&nbsp;</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155713_1666252639769.png\",\"createBy\":\"test\",\"createTime\":1666252902717,\"id\":\"1583005525338087425\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"26.306648\",\"longitude\":\"115.345428\",\"name\":\"将军园（苏园）\",\"sort\":36,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '13', null, '2022-10-20 16:01:43', null, null, null);
INSERT INTO `sys_log` VALUES ('1583006771885236225', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市寻乌县毛泽东寻乌调查纪念馆西北门旁\",\"antiepidemicPolicy\":\"无\",\"area\":\"寻乌县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252976471.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/航拍图_1666252987388.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/城市_1666252992848.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/古街_1666252996414.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/民俗_1666253001451.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/乡愁_1666253005597.jpg\",\"businessTime\":\"8:00-12:00，14:00-18:00，周一闭馆\",\"clockRadius\":100,\"contactNumber\":\"0797-2846986\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。寻乌县博物馆为县文广新旅局下属股级事业单位，位于寻乌县客家小镇崇文路，是一座集收藏、保护、研究、展示、教育为一体的综合性博物馆，2018年5月破土动工，2020年12月建成开馆试运行。博物馆占地面积9880平方米，建筑面积8211平方米，展厅面积3687平方米。地面上一、二、三层为展厅及办公区，地下一层为车库。馆内共有两个基本陈列，一楼为寻乌县城市风采展，二、三楼为寻乌县历史文化展。整个展览力求创新陈列理念，充分运用实物、图片，合理使用油画、场景复原、数字多媒体等先进的展示方法和手段，从多角度、多侧面向广大观众展示寻乌城乡建设发展的辉煌成就和寻乌丰富的历史文化内涵，让观众可以直观了解寻乌社会经济建设和历史文化的发展。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252969895.jpg\",\"createBy\":\"test\",\"createTime\":1666253199912,\"id\":\"1583006771860070402\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.947366\",\"longitude\":\"115.649\",\"name\":\"寻乌县博物馆\",\"sort\":36,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '6', null, '2022-10-20 16:06:40', null, null, null);
INSERT INTO `sys_log` VALUES ('1583006963145498626', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市寻乌县毛泽东寻乌调查纪念馆西北门旁\",\"antiepidemicPolicy\":\"无\",\"area\":\"寻乌县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252976471.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/航拍图_1666252987388.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/城市_1666252992848.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/古街_1666252996414.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/民俗_1666253001451.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/乡愁_1666253005597.jpg\",\"businessTime\":\"8:00-12:00，14:00-18:00，周一闭馆\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-2846986\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。寻乌县博物馆为县文广新旅局下属股级事业单位，位于寻乌县客家小镇崇文路，是一座集收藏、保护、研究、展示、教育为一体的综合性博物馆，2018年5月破土动工，2020年12月建成开馆试运行。博物馆占地面积9880平方米，建筑面积8211平方米，展厅面积3687平方米。地面上一、二、三层为展厅及办公区，地下一层为车库。馆内共有两个基本陈列，一楼为寻乌县城市风采展，二、三楼为寻乌县历史文化展。整个展览力求创新陈列理念，充分运用实物、图片，合理使用油画、场景复原、数字多媒体等先进的展示方法和手段，从多角度、多侧面向广大观众展示寻乌城乡建设发展的辉煌成就和寻乌丰富的历史文化内涵，让观众可以直观了解寻乌社会经济建设和历史文化的发展。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252969895.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583006771860070402\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.947366\",\"longitude\":\"115.649\",\"name\":\"寻乌县博物馆\",\"sort\":37,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666253245505,\"viewCount\":0}]', null, '13', null, '2022-10-20 16:07:26', null, null, null);
INSERT INTO `sys_log` VALUES ('1583008420523532289', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市章贡区红旗大道86号江西理工大学第二教学楼\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/1_1666253376995.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/2_1666253384156.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/3_1666253391172.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/4_1666253402729.jpg\",\"businessTime\":\"周一至周五，8:30-17:30\",\"clockRadius\":100,\"contactNumber\":\"18270740608\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。江西理工大学&ldquo;VR+红色教育&rdquo;教学研究基地，选取了苏区历史上具有重要意义的素材和事件，如大柏地伏击战、第三次反&ldquo;围剿&rdquo;、长征第一渡、一苏大、二苏大等事件，运用现代信息技术，通过实景建模，逼真还原场景，开发成VR项目，生动阐释中央苏区时期毛泽东的军事思想，根据地政权建设的理论和实践，党的群众路线等，展现了中国共产党在中央苏区践行的苏区精神。该基地深入研究了当代红色教育的特点和认知规律，积极创新红色教育的教学载体，以5G、大数据、云计算等现代信息技术为支撑，综合运用VR（虚拟现实）、AR（增强现实）、MR（混合现实）和流媒体、超高清等技术手段，构建全息化、可视化的教学流程，为学生提供沉浸式、交互式的学习体验，打造成了顺应教育技术革新趋势、辐射带动其他单位的红色教育VR基地。目前该基地已经成为学校思政课的实践教学基地、江西省中小学和其他单位的爱国主义教育基地。获批赣州市优秀科普示范基地、江西省第二批VR应用示范项目、江西省首批少先队校外实践教育基地。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/1_1666253373687.jpg\",\"createBy\":\"test\",\"createTime\":1666253592977,\"id\":\"1583008420494172161\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.854005\",\"longitude\":\"114.92998\",\"name\":\"江西理工大学“VR+红色教育”教学研究基地\",\"sort\":38,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '7', null, '2022-10-20 16:13:13', null, null, null);
INSERT INTO `sys_log` VALUES ('1583010071443529729', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市章贡区赣南师范学院大学生人文科技中心3层\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"8:30-12:00，14:30-17:30，周一闭馆\",\"clockRadius\":100,\"contactNumber\":\"19979752269\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/微信图片_20220920163043_1666253689216.jpg\",\"createBy\":\"test\",\"createTime\":1666253986576,\"id\":\"1583010071368032257\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.796859\",\"longitude\":\"114.88603\",\"name\":\"赣南师范大学中央苏区历史博物馆\",\"sort\":39,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '18', null, '2022-10-20 16:19:47', null, null, null);
INSERT INTO `sys_log` VALUES ('1583011728826949634', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市南康区赣州经济技术开发区新能源汽车城职教园唐龙大道\",\"antiepidemicPolicy\":\"无\",\"area\":\"南康区\",\"businessTime\":\"周一至周五，8:30-17:00\",\"clockRadius\":100,\"contactNumber\":\"0797-8069693\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。本科普基地现有占地面积500平方米，设有数字展厅，摄影棚，VR体验室，服装非遗手工艺工作室，直播展示基地等，集六大综合功能:收藏、研究、陈列展览、教育、交流、服务为一体，是一个完整的当代艺术、数字文创社科普馆。现有社科普工作人员8人，其中含非遗传承人1人，文化馆艺术馆馆长2人。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;结合赣南非遗特色，红色文化资源，爱国文化和客家文化，展出作品展现赣南地域特色，打造集史料、文化、艺术、观赏、视频游戏学习、原创VR体验、传统手工制作体验为一体特色艺术、数字文创、互动体验社科普基地，体现当代年轻人积极向上的思想，活动内容形式多样，有手工制作体验等环节，未来将开展丰富多彩的社科普及活动。将党的创新理论大众化通俗化上，让社科普更接&ldquo;地气&rdquo;，提升群众的艺术素养和人文素养，传播优秀传统文化、核心价值观等。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/9_1666254129521.jpg\",\"createBy\":\"test\",\"createTime\":1666254381725,\"id\":\"1583011728743063553\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.798255\",\"longitude\":\"114.771735\",\"name\":\"数字文创互动体验科普基地\",\"sort\":40,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '20', null, '2022-10-20 16:26:22', null, null, null);
INSERT INTO `sys_log` VALUES ('1583014606325014530', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市章贡区赣州经济技术开发区105国道\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/地质博物馆-1_1666254880216.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/地质博物馆-2_1666254883338.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/地质博物馆-3_1666254886431.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/江西省珠宝加工职业技能竞赛基地_1666254889754.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/宝石鉴定实训室_1666254893919.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/宝石镶嵌实训室_1666254898147.jpg\",\"businessTime\":\"周一至周五，9:00-12:00，14:30-17:00\",\"clockRadius\":100,\"contactNumber\":\"15927363730\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/地质博物馆-1_1666254875646.jpg\",\"createBy\":\"test\",\"createTime\":1666255067787,\"id\":\"1583014606295654401\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.802079\",\"longitude\":\"114.895558\",\"name\":\"珠宝玉石及地球科学社科普基地\",\"sort\":41,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '7', null, '2022-10-20 16:37:48', null, null, null);
INSERT INTO `sys_log` VALUES ('1583016030593212418', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市章贡区青春大道江西理工大学(红旗校区)\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/基地外景_1666255141881.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/基地内景1_1666255147269.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/基地内景2_1666255150607.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/基地内景3_1666255154712.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/基地内景4_1666255158681.jpg\",\"businessTime\":\"周日下午14:30-17:00\",\"clockRadius\":100,\"contactNumber\":\"王翔15603003980\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/基地外景_1666255138731.jpg\",\"createBy\":\"test\",\"createTime\":1666255407352,\"id\":\"1583016030534492161\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.853837\",\"longitude\":\"114.927429\",\"name\":\"江西理工大学中央苏区法治文化基地\",\"sort\":42,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '14', null, '2022-10-20 16:43:27', null, null, null);
INSERT INTO `sys_log` VALUES ('1583017268470734850', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市龙南市广场南路与广场西路交叉路口往北约140米\",\"antiepidemicPolicy\":\"无\",\"area\":\"龙南市\",\"businessTime\":\"周一至周五，8:30-12:00，14:30-17:30\",\"clockRadius\":100,\"contactNumber\":\"18779057500\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。龙南市新时代文明实践中心位于龙南市龙翔广场北侧，总占地面积600平米，依水而建，内有亭台、廊榭、庭院，环境优美宜人。实践中心设有中心调度区、&ldquo;学习强国&rdquo;线下学习区、图书阅览区、四点半课堂、志愿服务站、好人展示区、活动展示区、娱乐区、观影区、休闲茶吧区等10大功能区域，集思想引领、统筹调度、志愿服务、休闲娱乐、好人展示、成果展现等6大功能为一体，实现了新时代文明实践中心、融媒体中心、志愿服务中心、综合文化服务中心&ldquo;四中心&rdquo;融合，以及实践中心与实践所（站）的&ldquo;线上+线下&rdquo;联通互动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/b316c8710beed991c9f0a5f5d8018f3_1666255474293.jpg\",\"createBy\":\"test\",\"createTime\":1666255702493,\"id\":\"1583017268445569025\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.905064\",\"longitude\":\"114.79989\",\"name\":\"龙南市新时代文明实践中心\",\"sort\":42,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '6', null, '2022-10-20 16:48:22', null, null, null);
