INSERT INTO `sys_log` VALUES ('1583019677519568898', '2', '基地信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.add()', null, '[{\"address\":\"赣州市龙南市105国道与408县道交叉口西160米水口小学对面\",\"antiepidemicPolicy\":\"无\",\"area\":\"龙南市\",\"businessTime\":\"9:00-12:00，14:30-17:30\",\"clockRadius\":100,\"contactNumber\":\"18038224297\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。临塘乡新时代文明实践所位于临塘乡水口村，是由原水口小学改建而来，耗资300多万打造，总占地面积2000多平方米，分为文化广场和室内活动室两大部分。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;室外文化广场：主要是为群众提供休闲娱乐的公共空间与文化活动的场所。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;室内活动室：为满足乡村群众精神文化需求，按照积极创新、务实管用、群众满意的原则，突出学习、活动、服务三大功能，在这里集中设置了新时代文明实践所多功能活动厅、&ldquo;学习强国&rdquo;线下学习平台、综合文化站、妇女儿童之家、孝老食堂、老年活动中心、党群活动中心等。同时，配备了专职人员进行管理，做好日常开放服务管理工作。现在，这里已经成为群众愿意来、留得住、有获得感的活动阵地，党委政府宣传、组织、凝聚、服务群众的综合性服务平台，周边居民开展休闲娱乐、文化教育、交流活动的精神家园。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/实践所主体_1666255930925.jpg\",\"createBy\":\"test\",\"createTime\":1666256276858,\"id\":\"1583019677506985985\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.784199\",\"longitude\":\"114.80699\",\"name\":\"临塘乡新时代文明实践所\",\"sort\":43,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\"}]', null, '8', null, '2022-10-20 16:57:57', null, null, null);
