INSERT INTO `sys_log` VALUES ('1583294171303718913', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市崇义县上堡乡竹溪村村部\",\"antiepidemicPolicy\":\"无\",\"area\":\"崇义县\",\"businessTime\":\"全天候开放，8:30-12:00、14:30-18:00有讲解\",\"clockCount\":0,\"clockRadius\":200,\"contactNumber\":\"15970000991\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。上堡乡水稻科普基地位于竹溪村罗家组，毗邻万长山景区和上堡梯田景区木梓排板块的中间地带，项目占地面积110亩，总投资566万元，紧扣农业观光、稻作文化、科普教育主题，划分为7个区种植了101个水稻品种，布设了游步道、打谷场、科普长廊、水稻迷宫、观景平台、图案稻田、农耕体验区等内容，上堡乡水稻科普基地目前是国内最齐全、最丰富和最具特质的水稻种质资源圃。这也是全省第一个集&ldquo;研学+科普+农旅&rdquo;为一体的特色水稻科普基地，秉承&ldquo;传播稻作知识，弘扬农耕文化&rdquo;为宗旨，在木栈道两旁放置了二十四节气与农事谚语牌，带您领略古人智慧，促进粮食丰产增收，稳住&ldquo;米袋子&rdquo;。水稻博览园的打造既丰富了上堡的旅游业态，又策应了县委&ldquo;工业强县、生态富民、文旅融合&rdquo;的发展战略，是全面乡村振兴的一个缩影。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/828880268059320b36f8e997f17c6da_1666241596461.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1582961495984168961\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.74465\",\"longitude\":\"114.018849\",\"name\":\"上堡乡水稻科普基地\",\"sort\":18,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666321721272,\"viewCount\":16}]', null, '8', null, '2022-10-21 11:08:41', null, null, null);
