INSERT INTO `sys_log` VALUES ('1583342166502092802', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区红旗大道86号江西理工大学第二教学楼\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/1_1666253376995.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/2_1666253384156.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/3_1666253391172.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/4_1666253402729.jpg\",\"businessTime\":\"周一至周五，8:30-17:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"18270740608\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;江西理工大学&ldquo;VR+红色教育&rdquo;教学研究基地为赣州市社科普及基地，该基地选取了苏区历史上具有重要意义的素材和事件，如大柏地伏击战、第三次反&ldquo;围剿&rdquo;、长征第一渡、一苏大、二苏大等事件，运用现代信息技术，通过实景建模，逼真还原场景，开发成VR项目，生动阐释中央苏区时期毛泽东的军事思想，根据地政权建设的理论和实践，党的群众路线等，展现了中国共产党在中央苏区践行的苏区精神。该基地深入研究了当代红色教育的特点和认知规律，积极创新红色教育的教学载体，以5G、大数据、云计算等现代信息技术为支撑，综合运用VR（虚拟现实）、AR（增强现实）、MR（混合现实）和流媒体、超高清等技术手段，构建全息化、可视化的教学流程，为学生提供沉浸式、交互式的学习体验，打造成了顺应教育技术革新趋势、辐射带动其他单位的红色教育VR基地。目前该基地已经成为学校思政课的实践教学基地、江西省中小学和其他单位的爱国主义教育基地。获批赣州市优秀科普示范基地、江西省第二批VR应用示范项目、江西省首批少先队校外实践教育基地。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/1_1666253373687.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583008420494172161\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.854005\",\"longitude\":\"114.92998\",\"name\":\"江西理工大学“VR+红色教育”教学研究基地\",\"sort\":38,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666333164219,\"viewCount\":1}]', null, '7', null, '2022-10-21 14:19:24', null, null, null);
