INSERT INTO `sys_log` VALUES ('1583344404679176193', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市南康区镜坝镇园全村\",\"antiepidemicPolicy\":\"无\",\"area\":\"南康区\",\"businessTime\":\"9:00-17:30\",\"clockCount\":0,\"clockRadius\":500,\"contactNumber\":\"0797-6792665\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/593A9968_1666246070473.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1582978105780330497\",\"ifHot\":\"Y\",\"ifRecommend\":\"N\",\"latitude\":\"25.698503\",\"longitude\":\"114.761878\",\"name\":\"南康家居小镇\",\"sort\":25,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666333697843,\"viewCount\":6}]', null, '6', null, '2022-10-21 14:28:18', null, null, null);
INSERT INTO `sys_log` VALUES ('1583344809555341313', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区福寿沟博物馆旁边\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606(1)_1665914513683.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30170758(1)_1665914512963.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_20220930163657_1665914510519.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_20220930171035_1665914511208.jpg\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院为赣州市社科普及基地。该院横跨赣州老城区罗家巷、荷包塘、慈姑岭三条街，是市区现存最大的清代家族民居建筑群，大院始建于嘉庆年间（1799-1820），定型于民国初年，至今已有200年历史，为江西省文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院是清代中期至民国初年陆续建造的民居，是赣州乃至全省城区范围内现存最大的清代客家大屋，集中体现了赣南传统建筑的典型格式，是赣南一处珍贵的、人文内涵丰富的家族建筑群，是赣州古建筑的精华。&nbsp;</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院核心区已修复区域用于打造&ldquo;赣南客家文化博物馆&rdquo;。通过文字、图片、图表、文物、实物、场景再现以及现代全息等技术手段，多角度、多形式展现赣南客家人的生产生活情景。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606_1665648012232.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468610148327425\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.855513\",\"longitude\":\"114.952607\",\"name\":\"魏家大院\",\"sort\":5,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666333794374,\"viewCount\":27}]', null, '5', null, '2022-10-21 14:29:54', null, null, null);
INSERT INTO `sys_log` VALUES ('1583345154981441538', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区西津路8号\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"businessTime\":\"周一至周六，8:30-11:30，13:30-17:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"4009151588\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;阳明书院为江西省社科普及基地。该院位于江西赣州郁孤台下，原名濂溪书院。阳明书院是一座研究、挖掘、传扬王阳明心学的专业书院，集藏书售书、学术研讨、国学传授、阳明生平介绍、古琴教育、古玩鉴赏、书画作品和文房用品展示推介等为一体的综合性旅游点，已被列入赣州市郁孤台历史文化街区旅游景点。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;赣州阳明书院位于明代&ldquo;阳明书院&rdquo;旧址，占地2300平米，有效房间面积1580平米，是典型的三进式客家民居。学院内设仰德堂、良知堂、知行堂、传习堂、望德亭、&ldquo;三纲八目&rdquo;茶社、思归轩、阳明精舍（书院）、阳明手迹碑林、格竹园、阳明别苑等。书院内涉及王阳明的各类藏书已达5000余册。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/54279b33cf859dd8b3e5c4ca75a1095_1666232179619.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468987241422850\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.864054\",\"longitude\":\"114.937802\",\"name\":\"阳明书院\",\"sort\":6,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666333876730,\"viewCount\":42}]', null, '5', null, '2022-10-21 14:31:17', null, null, null);
