INSERT INTO `sys_log` VALUES ('1583347795333558274', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市寻乌县黄岗山公园西北侧约50米\",\"antiepidemicPolicy\":\"无\",\"area\":\"寻乌县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252976471.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/航拍图_1666252987388.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/城市_1666252992848.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/古街_1666252996414.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/民俗_1666253001451.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/乡愁_1666253005597.jpg\",\"businessTime\":\"8:00-12:00，14:00-18:00，周一闭馆\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-2846986\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;该基地为赣州市社科普及基地。寻乌县博物馆为县文广新旅局下属股级事业单位，位于寻乌县客家小镇崇文路，是一座集收藏、保护、研究、展示、教育为一体的综合性博物馆，2018年5月破土动工，2020年12月建成开馆试运行。博物馆占地面积9880平方米，建筑面积8211平方米，展厅面积3687平方米。地面上一、二、三层为展厅及办公区，地下一层为车库。馆内共有两个基本陈列，一楼为寻乌县城市风采展，二、三楼为寻乌县历史文化展。整个展览力求创新陈列理念，充分运用实物、图片，合理使用油画、场景复原、数字多媒体等先进的展示方法和手段，从多角度、多侧面向广大观众展示寻乌城乡建设发展的辉煌成就和寻乌丰富的历史文化内涵，让观众可以直观了解寻乌社会经济建设和历史文化的发展。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252969895.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583006771860070402\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.976349\",\"longitude\":\"115.633333\",\"name\":\"寻乌县博物馆\",\"sort\":37,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666334506237,\"viewCount\":10}]', null, '7', null, '2022-10-21 14:41:46', null, null, null);
