INSERT INTO `sys_log` VALUES ('1583352748466843650', '2', '题目信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.sub.controller.SubTitleController.add()', null, '[{\"subAnswerList\":[{\"analysis\":\"我们深入贯彻以人民为中心的发展思想，在幼有所育、学有所教、劳有所得、病有所医、老有所养、住有所居、弱有所扶上持续用力，建成世界上规模最大的教育体系、社会保障体系、医疗卫生体系，人民群众获得感、幸福感、安全感更加充实、更有保障、更可持续，共同富裕取得新成效。\",\"answer\":\"A\",\"createBy\":\"test\",\"createTime\":1666335687158,\"id\":\"1583352748445872130\",\"isLast\":0,\"sysOrgCode\":\"A02A02\",\"titleId\":\"1583352748420706305\"}],\"subType\":1,\"title\":\"十年来，我们建成（）的教育体系、社会保障体系、医疗卫生体系，\"}]', null, '11', null, '2022-10-21 15:01:27', null, null, null);
INSERT INTO `sys_log` VALUES ('1583352756519907330', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市寻乌县黄岗山公园西北侧约50米\",\"antiepidemicPolicy\":\"无\",\"area\":\"寻乌县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252976471.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/航拍图_1666252987388.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/城市_1666252992848.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/古街_1666252996414.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/民俗_1666253001451.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/乡愁_1666253005597.jpg\",\"businessTime\":\"8:00-12:00，14:00-18:00，周一闭馆\",\"clockCount\":2,\"clockRadius\":100,\"contactNumber\":\"0797-2846986\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;寻乌县博物馆为赣州市社科普及基地。该馆为寻乌县文广新旅局下属股级事业单位，位于寻乌县客家小镇崇文路，是一座集收藏、保护、研究、展示、教育为一体的综合性博物馆，2018年5月破土动工，2020年12月建成开馆试运行。博物馆占地面积9880平方米，建筑面积8211平方米，展厅面积3687平方米。地面上一、二、三层为展厅及办公区，地下一层为车库。馆内共有两个基本陈列，一楼为寻乌县城市风采展，二、三楼为寻乌县历史文化展。整个展览力求创新陈列理念，充分运用实物、图片，合理使用油画、场景复原、数字多媒体等先进的展示方法和手段，从多角度、多侧面向广大观众展示寻乌城乡建设发展的辉煌成就和寻乌丰富的历史文化内涵，让观众可以直观了解寻乌社会经济建设和历史文化的发展。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252969895.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583006771860070402\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.976349\",\"longitude\":\"115.633333\",\"name\":\"寻乌县博物馆\",\"sort\":37,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666335689061,\"video\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/10月21日_1666335563047.mp4\",\"viewCount\":26}]', null, '22', null, '2022-10-21 15:01:29', null, null, null);
INSERT INTO `sys_log` VALUES ('1583353169910509569', '2', '题目信息-添加', '2', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.sub.controller.SubTitleController.add()', null, '[{\"subAnswerList\":[{\"analysis\":\"马克思主义是我们立党立国、兴党兴国的根本指导思想。实践告诉我们，中国共产党为什么能，中国特色社会主义为什么好，归根到底是马克思主义行，是中国化时代化的马克思主义行。拥有马克思主义科学理论指导是我们党坚定信仰信念、把握历史主动的根本所在。\",\"answer\":\"A\",\"createBy\":\"test\",\"createTime\":1666335787635,\"id\":\"1583353169872760833\",\"isLast\":0,\"sysOrgCode\":\"A02A02\",\"titleId\":\"1583353169843400706\"}],\"subType\":1,\"title\":\"党的“二十大”报告指出，（）是我们立党立国、兴党兴国的根本指导思想。\"}]', null, '16', null, '2022-10-21 15:03:08', null, null, null);
