INSERT INTO `sys_log` VALUES ('1583372068563529729', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市寻乌县黄岗山公园西北侧约50米\",\"antiepidemicPolicy\":\"无\",\"area\":\"寻乌县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/正面图_1666252976471.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/航拍图_1666252987388.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/城市_1666252992848.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/古街_1666252996414.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/民俗_1666253001451.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/乡愁_1666253005597.jpg\",\"businessTime\":\"8:00-12:00，14:00-18:00，周一闭馆\",\"clockCount\":8,\"clockRadius\":100,\"contactNumber\":\"0797-2846986\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;寻乌县博物馆为赣州市社科普及基地。该馆为寻乌县文广新旅局下属股级事业单位，位于寻乌县客家小镇崇文路，是一座集收藏、保护、研究、展示、教育为一体的综合性博物馆，2018年5月破土动工，2020年12月建成开馆试运行。博物馆占地面积9880平方米，建筑面积8211平方米，展厅面积3687平方米。地面上一、二、三层为展厅及办公区，地下一层为车库。馆内共有两个基本陈列，一楼为寻乌县城市风采展，二、三楼为寻乌县历史文化展。整个展览力求创新陈列理念，充分运用实物、图片，合理使用油画、场景复原、数字多媒体等先进的展示方法和手段，从多角度、多侧面向广大观众展示寻乌城乡建设发展的辉煌成就和寻乌丰富的历史文化内涵，让观众可以直观了解寻乌社会经济建设和历史文化的发展。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-21161632_1666340282382.png\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583006771860070402\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.976349\",\"longitude\":\"115.633333\",\"name\":\"寻乌县博物馆\",\"sort\":37,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666340293422,\"video\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/10月21日_1666335563047.mp4\",\"viewCount\":72}]', null, '10', null, '2022-10-21 16:18:13', null, null, null);
INSERT INTO `sys_log` VALUES ('1583372302073016321', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市会昌县223省道南100米\",\"antiepidemicPolicy\":\"    省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"会昌县\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇为赣州市社科普及基地。该基地坐落在赣州市会昌县白鹅乡的梓坑村。这是一个客家原住民的典型村落，森林竹海、田园生活，生态环境十分优美。这也是一个红色村，当年留守苏区的党政军中央机关，集中驻扎在这个村子里。村里有苏区中央军区政治部旧址（下园坝新屋）、留守苏区中央运输连旧址（上园坝李氏宗祠）、留守苏区红军供销合作社旧址（上园坝）、留守苏区中央总供给部旧址（溪背新屋）、留守苏区中央兵工厂旧址（大塘湖林氏宗祠）、留守苏区中央国家银行旧址（白沙园）等6处列入赣州市第二批不可移动文物保护名录，2018年3月被列为省级文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;和君小镇由北京和君集团发起投资和建设，是江西省政府公布的江西省重点投资项目，也是江西省政府审定的省级特色小镇。2021年，小镇创办和君职业学院，这是全国第一所办在革命老区村子里的大学。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_202209281715163_1665467535715.jpg\",\"createBy\":\"admin\",\"createTime\":1665417600000,\"id\":\"1579711919324635137\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.838229\",\"longitude\":\"115.602885\",\"name\":\"赣州市红色文化研究会（和君小镇）\",\"sort\":12,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666340349100,\"viewCount\":9}]', null, '6', null, '2022-10-21 16:19:09', null, null, null);
