INSERT INTO `sys_log` VALUES ('1583372843020791809', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县大余县南安镇东山村菜园里(原大余县第三医院)\",\"antiepidemicPolicy\":\"无\",\"area\":\"大余县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/dybwg_1665915469847.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2acbf4e10b42ab3cfdf3f4c207b19bd_1665915494701.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d9b05796c3ac944154a36744efb330a_1665915486071.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/ed9acc760b40a99a3d10f0819185698_1665915484525.jpg\",\"businessTime\":\"9:00-12:00，14:30-16:30，周一闭馆\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-8721619\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; 大余县博物馆为赣州市社科普及基地。该馆成立于上世纪七十年代，经国家文物局审批备案，是一座集文物收藏、历史研究、社会教育、旅游观光为一体的综合性博物馆。馆藏文物2000余件，占地面积7.5亩，建筑面积3400.53㎡，设基本陈列展1个，临时展5个，为江西省博物馆协会理事单位。大余县博物馆通过文物陈展，让观众记得历史沧桑，看得见岁月印痕，护得住文化根脉，让大余的文化遗产焕发出更加耀眼的光彩。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/ed9acc760b40a99a3d10f0819185698_1666233727048.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580471538695266305\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.388169\",\"longitude\":\"114.368082\",\"name\":\"大余县博物馆\",\"sort\":9,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666340478072,\"viewCount\":40}]', null, '6', null, '2022-10-21 16:21:18', null, null, null);
INSERT INTO `sys_log` VALUES ('1583372977334988801', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市崇义县阳明大道(崇裕大观东侧约200米)\",\"antiepidemicPolicy\":\"无\",\"area\":\"崇义县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/cybwg_1665915136400.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/19ae057d6c8765d699e94f2f403df5f_1665915146136.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/83c469124d3a212840faf87320c67af_1665915144356.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/832cd14c3a07d1f76112d889fd08c8a_1665915144444.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/edf8c4d59be3bfc3465d75d740766df_1665915144452.jpg\",\"businessTime\":\"9:00-16:30，周一闭馆\",\"clockCount\":0,\"clockRadius\":200,\"contactNumber\":\"0797-381334\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/19ae057d6c8765d699e94f2f403df5f_1665648533059.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580471051933704194\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.67027\",\"longitude\":\"114.312337\",\"name\":\"崇义县博物馆\",\"sort\":8,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666340510072,\"viewCount\":50}]', null, '29', null, '2022-10-21 16:21:50', null, null, null);
INSERT INTO `sys_log` VALUES ('1583373152321351682', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市全南县陂头镇416乡道与星光路交叉口北160米\",\"antiepidemicPolicy\":\"无\",\"area\":\"全南县\",\"businessTime\":\"9:00-12:00,15:00-17:30,19:00-20:00，周一闭所\",\"clockCount\":0,\"clockRadius\":50,\"contactNumber\":\"杨娟18879788535\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;陂头镇新时代文明实践所为赣州市社科普及基地。该所位于陂头圩镇文化路与平安路交汇处，占地面积7771平方米，建筑面积2519平方米，整合原八一垦殖场文化中心、长城社区居家养老服务中心等场所，是集宣传教育、体育文艺、医疗康养、议事协商于一体的综合性邻里中心。所内功能完善，配套齐全，设有&ldquo;党建+&rdquo;乡村振兴展厅、军垦文化展厅（八一垦殖场场史馆）、知青文化展厅、廉政文化展厅、瑶族非遗传承馆等五大主题文化展厅；书香全南阅览室、科普驿站、消防体验室、舞蹈培训中心、棋牌书画室等五个文教互动阵地；日间照料中心、居家养老服务中心（孝老食堂）；早教活动中心、童心港湾室、康复理疗室等五类便民服务场所；人大代表联络站、政协委员联络工作站、人才驿站（乡贤馆）、志愿服务站、乡镇党校等五项基层工作平台；实践所内外共有30余处场所场地和功能室，可为广大群众提供理论宣讲、教育引导、志愿服务、文体培训、科学普及、移风易俗、普法宣传等形式多样的文明实践活动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/xsd_1665648187549.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580470377477038082\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.009168\",\"longitude\":\"114.589681\",\"name\":\"陂头镇新时代文明实践所\",\"sort\":7,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"无\",\"updateBy\":\"test\",\"updateTime\":1666340551814,\"viewCount\":13}]', null, '7', null, '2022-10-21 16:22:32', null, null, null);
