INSERT INTO `sys_log` VALUES ('1583376461333606402', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市南康区苏访贤大道南\",\"antiepidemicPolicy\":\"无\",\"area\":\"南康区\",\"businessTime\":\"24小时开放\",\"clockCount\":0,\"clockRadius\":200,\"contactNumber\":\"暂无\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/bb46b7565e59302dfc679876bab87bc_1666228136087.jpg\",\"createBy\":\"admin\",\"createTime\":1666108800000,\"id\":\"1582527571017998337\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.633477\",\"longitude\":\"114.753178\",\"name\":\"南康百家姓和谐城\",\"sort\":17,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666341340745,\"viewCount\":48}]', null, '6', null, '2022-10-21 16:35:41', null, null, null);
INSERT INTO `sys_log` VALUES ('1583376670151225346', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市南康区赣州经济技术开发区新能源汽车城职教园唐龙大道\",\"antiepidemicPolicy\":\"无\",\"area\":\"南康区\",\"businessTime\":\"周一至周五，8:30-17:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-8069693\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;数字文创互动体验科普基地为赣州市社科普及基地。该基地现有占地面积500平方米，设有数字展厅，摄影棚，VR体验室，服装非遗手工艺工作室，直播展示基地等，集六大综合功能:收藏、研究、陈列展览、教育、交流、服务为一体，是一个完整的当代艺术、数字文创社科普馆。现有社科普工作人员8人，其中含非遗传承人1人，文化馆艺术馆馆长2人。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;结合赣南非遗特色，红色文化资源，爱国文化和客家文化，展出作品展现赣南地域特色，打造集史料、文化、艺术、观赏、视频游戏学习、原创VR体验、传统手工制作体验为一体特色艺术、数字文创、互动体验社科普基地，体现当代年轻人积极向上的思想，活动内容形式多样，有手工制作体验等环节，未来将开展丰富多彩的社科普及活动。将党的创新理论大众化通俗化上，让社科普更接&ldquo;地气&rdquo;，提升群众的艺术素养和人文素养，传播优秀传统文化、核心价值观等。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/9_1666254129521.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583011728743063553\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.798255\",\"longitude\":\"114.771735\",\"name\":\"数字文创互动体验科普基地\",\"sort\":40,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666341390512,\"viewCount\":35}]', null, '25', null, '2022-10-21 16:36:31', null, null, null);
INSERT INTO `sys_log` VALUES ('1583377047697305602', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市兴国县将军大道附近\",\"antiepidemicPolicy\":\"无\",\"area\":\"兴国县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155713_1666252652205.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155618_1666252662795.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155548_1666252671045.png\",\"businessTime\":\"8:30-17:30，周一闭馆\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-5318997\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;将军园（苏园）为赣州市社科普及基地。该景区位于兴国将军大道南端，占地508亩，是我县著名的&ldquo;全国爱国主义教育示范基地&rdquo;，中央党校、国防大学等众多高等院校和相关单位的教育基地，是江西省首个通过国家级旅游服务业标准化试点项目验收的红色景区。景区作为我县最大的公共游览公园，集参观学习、旅游观光、休闲娱乐于一体，布局有将军园和苏区干部好作风纪念园两园。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;将军园由将军馆、将军广场、大型群雕、国防教育广场、休闲广场、将军湖、将军岛、上将亭等组成。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;将军馆2018年被评为&ldquo;全省十大精品馆&rdquo;，建筑面积4200平方米，布展面积3090平方米，展线长530米，屋顶是红军八角帽造型，展厅和大门由镰刀、斧头形状构成，将军馆一楼为兴国籍56位开国将军生平展；二楼为兴国籍省部军级领导干部简介，利用图片、实物、文字等形式再现了兴国籍将军们的英勇事迹。&nbsp;</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/屏幕截图2022-10-20155713_1666252639769.png\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583005525338087425\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"26.306648\",\"longitude\":\"115.345428\",\"name\":\"将军园（苏园）\",\"sort\":36,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666341480546,\"viewCount\":1}]', null, '5', null, '2022-10-21 16:38:01', null, null, null);
