INSERT INTO `sys_log` VALUES ('1583378438641758210', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市全南县龙源坝镇雅溪村\",\"antiepidemicPolicy\":\"无\",\"area\":\"全南县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/龙源坝镇雅溪古村落外景图_1666250410803.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/土围外景图_1666250426212.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/陈氏宗祠内景图_1666250433192.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/土围内景图_1666250457136.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/雅溪书院内景_1666250462496.jpg\",\"businessTime\":\"8:00-18:00\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"陈海全13879765359\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;龙源坝镇雅溪古村落社科普及基地为赣州市社科普及基地，该基地位于雅溪古村景区，雅溪古村景区2016年被列为第四批中国传统村落；2018年成功创建国家4A级旅游景区；2019年被评为省4A级乡村旅游点。景区内有石围、土围、陈氏宗祠家风家训廉政教育基地、博雅书吧、古韵戏台、客家民俗文化馆、二十四节气馆、农耕文化馆、汉服馆、雅溪书院等旅游业态。龙源坝镇雅溪古村落社科普及基地整合了雅溪古村景区的陈氏宗祠家风家训廉政教育基地、博雅书吧、古韵戏台、客家民俗文化馆、二十四节气馆、农耕文化馆、汉服馆、雅溪书院、游客服务中心和村部党员活动室、党员志愿服务站、妇女儿童之家、便民服务中心、矛盾纠纷调解室、心理咨询室、卫生室、村民理事会等资源，为开展社科普及宣传活动提供了充足的场地条件。此外，还成立了巾帼志愿服务小队、环境整治志愿服务小队、客家美食制作技艺传承志愿服务小队、文艺志愿服务小队、旅游景区志愿服务小队、党员志愿服务小队等多支志愿者队伍，常态化组织开展社科普及宣传活动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/龙源坝镇雅溪古村落外景图_1666250405632.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1582996006138667010\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.905891\",\"longitude\":\"114.477504\",\"name\":\"龙源坝镇雅溪古村落\",\"sort\":32,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666341812170,\"viewCount\":1}]', null, '8', null, '2022-10-21 16:43:32', null, null, null);
