INSERT INTO `sys_log` VALUES ('1583635424117522434', '2', '基地信息-编辑', '3', 'test', '测试', '106.226.14.35', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市大余县水口寺路36号\",\"antiepidemicPolicy\":\"省内低风险地区需持72小时内核酸检测阴性证明，有省内中风险区旅居史的游客需出示48小时核酸阴性证明。\",\"area\":\"大余县\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/dybwg_1665915469847.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2acbf4e10b42ab3cfdf3f4c207b19bd_1665915494701.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/d9b05796c3ac944154a36744efb330a_1665915486071.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/ed9acc760b40a99a3d10f0819185698_1665915484525.jpg\",\"businessTime\":\"9:00-12:00，14:30-16:30，周一闭馆\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-8721619\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; 大余县博物馆为赣州市社科普及基地。该馆成立于上世纪七十年代，经国家文物局审批备案，是一座集文物收藏、历史研究、社会教育、旅游观光为一体的综合性博物馆。馆藏文物2000余件，占地面积7.5亩，建筑面积3400.53㎡，设基本陈列展1个，临时展5个，为江西省博物馆协会理事单位。大余县博物馆通过文物陈展，让观众记得历史沧桑，看得见岁月印痕，护得住文化根脉，让大余的文化遗产焕发出更加耀眼的光彩。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/ed9acc760b40a99a3d10f0819185698_1666233727048.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580471538695266305\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.390123\",\"longitude\":\"114.372903\",\"name\":\"大余县博物馆\",\"sort\":9,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666403082284,\"viewCount\":42}]', null, '7', null, '2022-10-22 09:44:42', null, null, null);
