INSERT INTO `sys_log` VALUES ('1583635971151233026', '2', '基地信息-编辑', '3', 'test', '测试', '106.226.14.35', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市南康区赣州经济技术开发区新能源汽车城职教园唐龙大道\",\"antiepidemicPolicy\":\"无\",\"area\":\"南康区\",\"businessTime\":\"周一至周五，8:30-17:00\",\"clockCount\":0,\"clockRadius\":400,\"contactNumber\":\"0797-8069693\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;数字文创互动体验科普基地为赣州市社科普及基地。该基地现有占地面积500平方米，设有数字展厅，摄影棚，VR体验室，服装非遗手工艺工作室，直播展示基地等，集六大综合功能:收藏、研究、陈列展览、教育、交流、服务为一体，是一个完整的当代艺术、数字文创社科普馆。现有社科普工作人员8人，其中含非遗传承人1人，文化馆艺术馆馆长2人。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;结合赣南非遗特色，红色文化资源，爱国文化和客家文化，展出作品展现赣南地域特色，打造集史料、文化、艺术、观赏、视频游戏学习、原创VR体验、传统手工制作体验为一体特色艺术、数字文创、互动体验社科普基地，体现当代年轻人积极向上的思想，活动内容形式多样，有手工制作体验等环节，未来将开展丰富多彩的社科普及活动。将党的创新理论大众化通俗化上，让社科普更接&ldquo;地气&rdquo;，提升群众的艺术素养和人文素养，传播优秀传统文化、核心价值观等。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/9_1666254129521.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583011728743063553\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.798255\",\"longitude\":\"114.771735\",\"name\":\"数字文创互动体验科普基地\",\"sort\":40,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666403212705,\"viewCount\":37}]', null, '9', null, '2022-10-22 09:46:53', null, null, null);
