INSERT INTO `sys_log` VALUES ('1583827741512302594', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区赣南师范学院大学生人文科技中心3层\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"audio\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/赣南师范大学中央苏区历史博物馆配乐_1666448926395.mp3\",\"businessTime\":\"8:30-12:00，14:30-17:30，周一闭馆\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"19979752269\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/微信图片_20220920163043_1666253689216.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583010071368032257\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.796859\",\"longitude\":\"114.88603\",\"name\":\"赣南师范大学中央苏区历史博物馆\",\"sort\":39,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666448934101,\"viewCount\":0}]', null, '229', null, '2022-10-22 22:28:54', null, null, null);
INSERT INTO `sys_log` VALUES ('1583828052041793537', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区红旗大道86号江西理工大学第二教学楼\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"audio\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/江西理工大学VR红色教育教学研究基地配乐_1666449004435.mp3\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/1_1666253376995.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/2_1666253384156.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/3_1666253391172.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/4_1666253402729.jpg\",\"businessTime\":\"周一至周五，8:30-17:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"18270740608\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;江西理工大学&ldquo;VR+红色教育&rdquo;教学研究基地为赣州市社科普及基地，该基地选取了苏区历史上具有重要意义的素材和事件，如大柏地伏击战、第三次反&ldquo;围剿&rdquo;、长征第一渡、一苏大、二苏大等事件，运用现代信息技术，通过实景建模，逼真还原场景，开发成VR项目，生动阐释中央苏区时期毛泽东的军事思想，根据地政权建设的理论和实践，党的群众路线等，展现了中国共产党在中央苏区践行的苏区精神。该基地深入研究了当代红色教育的特点和认知规律，积极创新红色教育的教学载体，以5G、大数据、云计算等现代信息技术为支撑，综合运用VR（虚拟现实）、AR（增强现实）、MR（混合现实）和流媒体、超高清等技术手段，构建全息化、可视化的教学流程，为学生提供沉浸式、交互式的学习体验，打造成了顺应教育技术革新趋势、辐射带动其他单位的红色教育VR基地。目前该基地已经成为学校思政课的实践教学基地、江西省中小学和其他单位的爱国主义教育基地。获批赣州市优秀科普示范基地、江西省第二批VR应用示范项目、江西省首批少先队校外实践教育基地。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/1_1666253373687.jpg\",\"createBy\":\"test\",\"createTime\":1666195200000,\"id\":\"1583008420494172161\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.854005\",\"longitude\":\"114.92998\",\"name\":\"江西理工大学“VR+红色教育”教学研究基地\",\"sort\":38,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666449008358,\"viewCount\":2}]', null, '8', null, '2022-10-22 22:30:08', null, null, null);
INSERT INTO `sys_log` VALUES ('1583828114243321858', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区西津路8号\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"audio\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/阳明书院配乐_1666449019089.mp3\",\"businessTime\":\"周一至周六，8:30-11:30，13:30-17:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"4009151588\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;阳明书院为江西省社科普及基地。该院位于江西赣州郁孤台下，原名濂溪书院。阳明书院是一座研究、挖掘、传扬王阳明心学的专业书院，集藏书售书、学术研讨、国学传授、阳明生平介绍、古琴教育、古玩鉴赏、书画作品和文房用品展示推介等为一体的综合性旅游点，已被列入赣州市郁孤台历史文化街区旅游景点。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;赣州阳明书院位于明代&ldquo;阳明书院&rdquo;旧址，占地2300平米，有效房间面积1580平米，是典型的三进式客家民居。学院内设仰德堂、良知堂、知行堂、传习堂、望德亭、&ldquo;三纲八目&rdquo;茶社、思归轩、阳明精舍（书院）、阳明手迹碑林、格竹园、阳明别苑等。书院内涉及王阳明的各类藏书已达5000余册。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/54279b33cf859dd8b3e5c4ca75a1095_1666232179619.jpg\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468987241422850\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.864054\",\"longitude\":\"114.937802\",\"name\":\"阳明书院\",\"sort\":6,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666449023186,\"viewCount\":47}]', null, '10', null, '2022-10-22 22:30:23', null, null, null);
INSERT INTO `sys_log` VALUES ('1583828178701385729', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市章贡区福寿沟博物馆旁边\",\"antiepidemicPolicy\":\"无\",\"area\":\"章贡区\",\"audio\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/魏家大院配乐_1666449035567.mp3\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606(1)_1665914513683.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30170758(1)_1665914512963.png,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_20220930163657_1665914510519.jpg,https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/微信图片_20220930171035_1665914511208.jpg\",\"businessTime\":\"9:00-17:00\",\"clockCount\":0,\"clockRadius\":100,\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院为赣州市社科普及基地。该院横跨赣州老城区罗家巷、荷包塘、慈姑岭三条街，是市区现存最大的清代家族民居建筑群，大院始建于嘉庆年间（1799-1820），定型于民国初年，至今已有200年历史，为江西省文物保护单位。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院是清代中期至民国初年陆续建造的民居，是赣州乃至全省城区范围内现存最大的清代客家大屋，集中体现了赣南传统建筑的典型格式，是赣南一处珍贵的、人文内涵丰富的家族建筑群，是赣州古建筑的精华。&nbsp;</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;魏家大院核心区已修复区域用于打造&ldquo;赣南客家文化博物馆&rdquo;。通过文字、图片、图表、文物、实物、场景再现以及现代全息等技术手段，多角度、多形式展现赣南客家人的生产生活情景。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/temp/2022-09-30164606_1665648012232.png\",\"createBy\":\"admin\",\"createTime\":1665590400000,\"id\":\"1580468610148327425\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.855513\",\"longitude\":\"114.952607\",\"name\":\"魏家大院\",\"sort\":5,\"status\":1,\"sysOrgCode\":\"A01\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666449038548,\"viewCount\":30}]', null, '16', null, '2022-10-22 22:30:39', null, null, null);
