INSERT INTO `sys_log` VALUES ('1584708865730019330', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市瑞金市金鑫大道附近\",\"antiepidemicPolicy\":\"无\",\"area\":\"瑞金市\",\"audio\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/4中共中央政治局旧址配乐_1666659006116.mp3\",\"banner\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/00c45ce3088a9848e94a6dd5a853cb6_1666257450296.jpg\",\"businessTime\":\"8:30-17:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"0797-2522063\",\"content\":\"<p>&nbsp; &nbsp; &nbsp; &nbsp; 中共中央政治局旧址为国家级社科普及基地&mdash;&mdash;中央革命根据地纪念馆子基地。该旧址位于瑞金市沙洲坝镇下肖。1933年1月，中共临时中央从上海迁来瑞金驻扎此地，同年4月与从叶坪搬迁到此的中共苏区中央局合并，组建新的中共中央局。在此办公的机构有组织部、宣传部、白区工作部、妇女部、党务委员会等。博古、张闻天、陈云、李维汉、邓颖超、金维映、陆定一、毛泽覃等在这里工作、居住过。</p>\\n<p>&nbsp; &nbsp; &nbsp; &nbsp;1934年7月，中共中央政治局迁驻瑞金云石山马道口。1961年该旧址公布为全国重点文物保护单位。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/00c45ce3088a9848e94a6dd5a853cb6_1666257443863.jpg\",\"createBy\":\"test\",\"createTime\":1666257564000,\"id\":\"1583025076566089730\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"25.870181\",\"longitude\":\"115.99888\",\"name\":\"中共中央政治局旧址\",\"sort\":48,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666659010707,\"viewCount\":2}]', null, '8', null, '2022-10-25 08:50:11', null, null, null);
