INSERT INTO `sys_log` VALUES ('1584709526152544257', '2', '基地信息-编辑', '3', 'test', '测试', '113.194.93.5', 'org.jeecg.modules.demo.base.controller.BaseInfoController.edit()', null, '[{\"address\":\"赣州市龙南市广场南路与广场西路交叉路口往北约140米\",\"antiepidemicPolicy\":\"无\",\"area\":\"龙南市\",\"audio\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/video/9龙南市新时代文明实践中心配乐_1666659162199.mp3\",\"businessTime\":\"周一至周五，8:30-12:00，14:30-17:30\",\"clockCount\":0,\"clockRadius\":100,\"contactNumber\":\"18779057500\",\"content\":\"<p style=\\\"text-align: justify;\\\">&nbsp; &nbsp; &nbsp; &nbsp;龙南市新时代文明实践中心为赣州市社科普及基地。该中心位于龙南市龙翔广场北侧，总占地面积600平米，依水而建，内有亭台、廊榭、庭院，环境优美宜人。实践中心设有中心调度区、&ldquo;学习强国&rdquo;线下学习区、图书阅览区、四点半课堂、志愿服务站、好人展示区、活动展示区、娱乐区、观影区、休闲茶吧区等10大功能区域，集思想引领、统筹调度、志愿服务、休闲娱乐、好人展示、成果展现等6大功能为一体，实现了新时代文明实践中心、融媒体中心、志愿服务中心、综合文化服务中心&ldquo;四中心&rdquo;融合，以及实践中心与实践所（站）的&ldquo;线上+线下&rdquo;联通互动。</p>\",\"cover\":\"https://gzqkl.oss-cn-hangzhou.aliyuncs.com/gzsk/image/b316c8710beed991c9f0a5f5d8018f3_1666255474293.jpg\",\"createBy\":\"test\",\"createTime\":1666255702000,\"id\":\"1583017268445569025\",\"ifHot\":\"N\",\"ifRecommend\":\"N\",\"latitude\":\"24.905064\",\"longitude\":\"114.79989\",\"name\":\"龙南市新时代文明实践中心\",\"sort\":43,\"status\":1,\"sysOrgCode\":\"A02A02\",\"ticketInfo\":\"免费\",\"updateBy\":\"test\",\"updateTime\":1666659168165,\"viewCount\":12}]', null, '6', null, '2022-10-25 08:52:48', null, null, null);
